import {ARENAS,hero,synergy,TACTICS,COMMANDS,canCommand,upcomingTurns} from './engine.mjs?v=5';
export function arenaMarkup(game,battle,playing,speed,lastEvent,resultVisible,{icon,esc,portrait}){
 const a=ARENAS.find(a=>a.id===game.arena);
 const total=side=>battle?battle.fighters[side].reduce((n,f)=>n+f.hp,0):0;
 const max=side=>battle?battle.fighters[side].reduce((n,f)=>n+f.maxHp,0):1;
 return `<main class="arena-page ${battle?'in-battle':''}"><section class="intro arena-intro"><div><div class="eyebrow"><span class="tiny-square"></span> SON SÖZ ARENANIN</div><h1>İki takım.<br><em>Tek kazanan.</em></h1><p>${battle?'Enerjini biriktir. Doğru anda müdahale et.':'Savaş alanını seç. Şansı ayarla. Mücadeleyi başlat.'}</p></div><div class="match-meta"><span class="session-tag">${battle?`TUR ${String(battle.round).padStart(2,'0')}`:'TAKIMLAR HAZIR'}</span><button class="text-button" data-action="setup">${icon('refresh')} Yeni oyun</button></div></section>
 ${!battle?`<div class="arena-config"><div><span class="eyebrow">SAVAŞ ALANI</span><div class="arena-options">${ARENAS.map(x=>`<button data-action="map" data-id="${x.id}" class="arena-option ${game.arena===x.id?'selected':''}"><span class="map-icon map-${x.id}">${icon(x.id==='city'?'bolt':x.id==='asgard'?'star':'shield')}</span><b>${x.name}</b><span>${x.desc}</span>${game.arena===x.id?icon('check'):''}</button>`).join('')}</div></div><div class="luck-setting"><label for="luck">Şans faktörü <strong id="luck-value">%${game.luck}</strong></label><input id="luck" type="range" min="0" max="25" value="${game.luck}"><p>Kritik vuruş olasılığı ve hasar sapması.<br>%0: sabit hasar; hızdan gelen kaçış devam eder.</p><button class="primary" data-action="start">Mücadeleyi başlat ${icon('play')}</button></div></div>`:''}
 <section class="cinema-arena map-${a.id}" aria-label="${a.name} üç boyutlu savaş alanı">
 <div class="arena-scene" id="arena-scene" role="img" aria-label="Kahramanların hareket ettiği 3B ${a.name} arenası"></div><div class="cinema-vignette"></div>
 <div class="cinema-top"><span><span class="live-dot"></span>${a.label}</span>${battle&&!battle.done?`<button class="scene-pause" data-action="toggle-play" aria-label="Arena mücadelesini ${playing?'duraklat':'devam ettir'}">${playing?'Ⅱ CANLI MÜCADELE':'▷ DURAKLATILDI'}</button>`:`<span>${battle?'MÜCADELE BİTTİ':'MÜCADELEYE HAZIR'}</span>`}</div>
 <div class="cinema-score"><div class="p0"><span>OYUNCU 01 · UYUM +%${synergy(game.players[0].team)}</span><h2>${esc(game.players[0].name)}</h2><div class="team-health"><i style="width:${battle?total(0)/max(0)*100:100}%"></i></div></div><div class="cinema-vs">VS<small>${battle?'TUR '+battle.round:'ARENA'}</small></div><div class="p1"><span>OYUNCU 02 · UYUM +%${synergy(game.players[1].team)}</span><h2>${esc(game.players[1].name)}</h2><div class="team-health"><i style="width:${battle?total(1)/max(1)*100:100}%"></i></div></div></div>
 <div class="arena-command-flash" id="arena-command-flash"></div><div class="arena-actor-labels" id="arena-actor-labels"></div><div class="arena-hit-label" id="arena-hit-label"></div>
 <div class="action-caption ${lastEvent?.special?'is-special':''}" aria-live="polite">${lastEvent?`<div class="exchange-pair">${portrait(hero(lastEvent.attacker))}<span><b>${hero(lastEvent.attacker).name}</b><small>${lastEvent.special?lastEvent.skill:lastEvent.overdrive?'Güç patlaması':'Saldırı'} <i>→</i> ${hero(lastEvent.target).name}</small></span><strong class="exchange-damage">${lastEvent.dodge?'KAÇIŞ':lastEvent.damage===0&&lastEvent.absorbed?'KALKAN':'−'+lastEvent.damage}<small>${lastEvent.crit?'KRİTİK':lastEvent.absorbed?'KALKAN −'+lastEvent.absorbed:'HASAR'}</small></strong>${portrait(hero(lastEvent.target))}</div><div class="exchange-status"><span class="exchange-phase">HAMLE</span><span>${lastEvent.knockout?'RAKİP ELENDİ':lastEvent.special?'ÖZEL YETENEK':lastEvent.overdrive?'+%25 GÜÇ':''}</span></div><div class="exchange-progress"><i></i></div>`:'<span>Takımlar yerlerini aldı</span><b>MÜCADELEYE HAZIR</b>'}</div>

 ${battle&&!battle.done?quickCommands(game,battle,esc):''}<div class="arena-camera-controls">${battle&&!battle.done?`<div class="scene-speeds">${[1,2,4].map(n=>`<button data-action="speed" data-id="${n}" class="${speed===n?'active':''}" aria-label="Arena oynatma hızı ${n}×">${n}×</button>`).join('')}</div>`:''}<button data-action="camera" data-id="follow" class="${!game.camera||game.camera==='follow'?'active':''}" aria-label="Sinematik kamera">SİNEMA</button><button data-action="camera" data-id="wide" class="${game.camera==='wide'?'active':''}" aria-label="Geniş kamera">GENİŞ</button><button data-action="camera" data-id="close" class="${game.camera==='close'?'active':''}" aria-label="Yakın kamera">YAKIN</button><button data-action="fullscreen" aria-label="Arenayı tam ekran aç" title="Tam ekran">⛶</button></div>
 ${battle?.done&&resultVisible?`<div class="result-overlay"><div class="eyebrow">${battle.decision?'40 TUR · KALAN CAN ORANI':'MÜCADELE TAMAMLANDI'}</div><span class="winner-icon">${icon('star')}</span><h2>${battle.winner===null?'Berabere!':esc(game.players[battle.winner].name)+' kazandı!'}</h2><p>${battle.round} tur · ${battle.events.length} hamle · ${battle.events.filter(e=>e.crit).length} kritik vuruş · ${battle.commands.length} komut</p><div><button class="primary" data-action="rematch">Aynı takımlarla rövanş ${icon('refresh')}</button><button class="glass-button" data-action="setup">Yeni oyun</button></div></div>`:''}</section>
 ${battle&&!battle.done?turnTimeline(battle,portrait,playing):''}${battle&&!battle.done?tacticalPanels(game,battle,esc):''}<div class="arena-rosters">${game.players.map((p,side)=>`<div class="arena-roster side-${side}">${p.team.map(id=>{const f=battle?.fighters[side].find(f=>f.id===id),h=hero(id);return `<button class="combat-roster-hero ${f?.hp===0?'eliminated':''} ${lastEvent?.attacker===id?'active':''}" data-action="detail" data-id="${id}" aria-label="${h.name} detayları">${portrait(h)}<div><b>${h.name}</b><span>${f?f.hp===0?'ELENDİ':`${f.hp}/${f.maxHp} CAN${f.shield?' · '+f.shield+' KALKAN':''} · ÖZEL ${f.actions%3}/3`:h.type+(h.flight?' · UÇUŞ':'')}</span></div><i class="mini-health"><i style="width:${f?f.hp/f.maxHp*100:100}%"></i></i></button>`;}).join('')}</div>`).join('')}</div>
 ${battle?`<div class="battle-controls"><div><button class="outline" data-action="toggle-play" ${battle.done?'disabled':''}>${icon(playing?'pause':'play')}${playing?'Duraklat':'Devam et'}</button><button class="outline" data-action="step" ${playing||battle.done?'disabled':''}>Tek hamle ${icon('arrow')}</button></div><div class="speed-control"><span>Oynatma hızı</span>${[1,2,4].map(n=>`<button data-action="speed" data-id="${n}" class="${speed===n?'active':''}">${n}×</button>`).join('')}</div></div><section class="battle-log"><div class="section-line"><h2>MÜCADELE GÜNLÜĞÜ</h2><span class="muted">Son ${Math.min(battle.events.length,30)} hamle</span></div>${battle.commands.length?`<div class="command-history" aria-label="Kullanılan savaş komutları">${battle.commands.slice(-12).reverse().map(e=>`<span class="p${e.side}"><b>T${e.round} · ${esc(game.players[e.side].name)}</b> ${e.name}${e.amount?' +'+e.amount+(e.id==='rally'?' can':' kalkan'):' · 3 saldırı +%25'}</span>`).join('')}</div>`:''}<div class="log-entries" aria-live="polite">${battle.events.slice(-30).reverse().map(e=>`<div class="log-entry"><span class="log-round">T${e.round}</span><span class="log-dot p${e.side}"></span><p><b>${hero(e.attacker).name}</b> → ${hero(e.target).name} <strong>${e.dodge?'KAÇIŞ':e.damage+' hasar'}</strong>${e.special?`<span class="log-badge">${e.skill}</span>`:''}${e.crit?'<span class="log-badge critical">KRİTİK</span>':''}${e.knockout?'<span class="log-badge">ELENDİ</span>':''}${e.extras.length?`<small>${e.extras.join(' · ')}</small>`:''}</p></div>`).join('')||'<p class="log-empty">İlk hamle bekleniyor…</p>'}</div></section>`:''}</main>`;
}

function tacticalPanels(game,battle,esc){return `<section class="tactical-deck" aria-label="Savaş komutları"><div class="tactics-heading"><div><span class="eyebrow">SAVAŞIN İÇİNDESİN</span><h2>Hamleni beklet. Anını seç.</h2></div><p>Her saldırı +8, alınan her saldırı +4 enerji.<br>Komutlar arasında 3 takım hamlesi gerekir.</p></div><div class="tactical-sides">${game.players.map((p,side)=>{const c=battle.control[side],bot=game.mode==='bot'&&side===1,remaining=Math.max(0,3-(c.turns-c.commandAt));return `<div class="tactical-panel side-${side}"><div class="tactical-top"><strong>${esc(p.name)}${bot?' · BOT':''}</strong><span><b>${c.energy}</b> / 100 ENERJİ</span></div><div class="energy-track"><i style="width:${c.energy}%"></i></div><div class="stance-row">${TACTICS.map(t=>`<button data-action="tactic" data-side="${side}" data-id="${t.id}" class="${c.tactic===t.id?'active':''}" title="${t.desc}" aria-pressed="${c.tactic===t.id}" ${bot||c.turns-c.tacticAt<2?'disabled':''}>${t.name}</button>`).join('')}</div><p class="tactic-description">${TACTICS.find(t=>t.id===c.tactic).desc}${c.turns-c.tacticAt<2?' · Değişim için '+(2-c.turns+c.tacticAt)+' takım hamlesi':''}</p><div class="command-row">${COMMANDS.map(cmd=>`<button data-action="command" data-side="${side}" data-id="${cmd.id}" ${bot||!canCommand(battle,side,cmd.id)?'disabled':''} aria-label="${esc(p.name)}: ${cmd.name}" title="${cmd.desc}"><span>${cmd.symbol}</span><b>${cmd.name}</b><small>${cmd.cost} enerji</small></button>`).join('')}</div><div class="tactical-bottom"><label>Hedef <select data-focus-side="${side}" aria-label="${esc(p.name)} hedef seçimi" ${bot?'disabled':''}><option value="">Otomatik</option>${battle.fighters[1-side].filter(f=>f.hp>0).map(f=>`<option value="${f.id}" ${c.focus===f.id?'selected':''}>${hero(f.id).name}</option>`).join('')}</select></label><span>${c.overdrive?c.overdrive+' güçlü saldırı kaldı':remaining?'Komut: '+remaining+' hamle sonra':'Komut hazır'}</span></div>${battle.commands.filter(e=>e.side===side).length?`<p class="last-command">Son komut: ${battle.commands.filter(e=>e.side===side).at(-1).name} · Tur ${battle.commands.filter(e=>e.side===side).at(-1).round}</p>`:''}</div>`;}).join('')}</div><details class="command-help"><summary>Komutlar ne yapar?</summary><p>Boşluk: duraklat / devam et. Sağ ok: duraklatılmışken tek hamle. 1–2–3: oyuncu 1 komutları; 7–8–9: oyuncu 2 komutları. Arenadaki rakip etiketine tıklayarak hedef seçebilirsin.</p><p>${COMMANDS.map(c=>`<b>${c.name}:</b> ${c.desc}`).join(' &nbsp; · &nbsp; ')} Hedef seçimi takımının saldırılarını seçtiğin yaşayan rakibe yönlendirir. Elenince otomatik hedefe dönülür.</p></details></section>`;}

function quickCommands(game,battle,esc){return `<div class="quick-command-dock" aria-label="Arena hızlı komutları">${game.players.map((p,side)=>`<div class="quick-side side-${side}"><div><b>${esc(p.name)}</b><span>↯ ${battle.control[side].energy}</span></div><div>${COMMANDS.map(c=>`<button data-action="command" data-side="${side}" data-id="${c.id}" ${game.mode==='bot'&&side===1||!canCommand(battle,side,c.id)?'disabled':''} title="${c.name}: ${c.desc} (${c.cost} enerji) · ${side===0?COMMANDS.indexOf(c)+1:COMMANDS.indexOf(c)+7} tuşu" aria-label="Arena ${esc(p.name)}: ${c.name}"><span>${c.symbol}</span><b>${c.id==='overdrive'?'GÜÇ':c.id==='barrier'?'KALKAN':'CAN'}</b><small>${c.cost}</small></button>`).join('')}</div></div>`).join('')}</div>`;}

function turnTimeline(battle,portrait,playing){const next=upcomingTurns(battle);return `<section class="turn-timeline" aria-label="Sıradaki hamleler"><div><span class="eyebrow">SIRADAKİ HAMLELER</span><p>${battle.round?'Hız sırası · tur '+battle.round:'Hız, ilk hamlede sırayı belirler.'}</p></div><div class="turn-line">${next.length?next.map((f,i)=>`<div class="turn-card side-${f.side} ${f.special?'is-special':''}">${portrait(hero(f.id))}<div><b>${hero(f.id).name}</b><small>${f.special?'↯ ÖZEL SALDIRI':i===0?'SIRADAKİ':'NORMAL SALDIRI'}</small></div><span>${i+1}</span></div>`).join(''):`<p class="turn-wait">${battle.round?'Yeni turun sırası sonraki hamlede belirlenir.':'Takımlar yerlerini alıyor…'}</p>`}</div><button data-action="toggle-play" class="tactical-pause" aria-label="${playing?'Taktik molası':'Mücadeleye dön'}">${playing?'Ⅱ Taktik molası':'▷ Mücadeleye dön'} <small>BOŞLUK</small></button></section>`;}
